<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Cerberus booking update</title></head><body style="margin:0;background:#f4f1e8;color:#1a252a;font:15px/1.6 Arial,sans-serif"><div style="max-width:620px;margin:28px auto;background:white;border-radius:10px;overflow:hidden"><header style="background:#182329;color:white;padding:22px 28px;font-size:20px;font-weight:bold;letter-spacing:3px">CERBERUS<div style="color:#d1bb83;font-size:10px;letter-spacing:1px">PRE-PURCHASE VEHICLE INSPECTIONS</div></header><main style="padding:28px"><h1 style="font-size:25px">{{ match($event) {'confirmed' => 'Your appointment is confirmed', 'cancelled' => 'Your booking has been cancelled', 'rescheduled' => 'Your appointment has changed', default => 'We received your request'} }}</h1><p>Hello {{ $booking->customer->full_name }},</p><p>{{ match($event) {'confirmed' => 'Your Cerberus vehicle inspection appointment has been confirmed.', 'cancelled' => 'Your Cerberus inspection booking has been cancelled. Contact us if you have questions.', 'rescheduled' => 'The appointment details for your Cerberus inspection have changed.', default => 'We have received your inspection request. Your preferred times are not confirmed; our team will contact you to arrange an appointment.'} }}</p><div style="background:#f5f3ed;padding:16px;border-radius:7px"><strong>Reference:</strong> {{ $booking->booking_reference }}<br><strong>Vehicle:</strong> {{ $booking->vehicle->registration }}<br><strong>Package:</strong> {{ $booking->package->name }}<br><strong>Estimated quote:</strong> {{ $booking->currency }} {{ number_format((float) $booking->quoted_total, 2) }}@if ($booking->appointment_at)<br><strong>Appointment:</strong> {{ $booking->appointment_at->format('D j M Y, H:i') }}@endif</div><p style="color:#687176;font-size:12px">This message confirms the booking details shown above. No payment has been taken.</p></main></div></body></html>
